/** Helper to get the TurtleWoW database link */
const getTurtleWoWLink = (spellId: number) => 
  `https://database.turtlecraft.gg/?spell=${spellId}`;

/** Side-by-side comparison component */
function SideBySide({ spell }: { spell: WoWSpell }) {
  return (
    <div className="flex flex-col items-center gap-6">
      <div className="flex gap-8 items-start">
        <div className="flex flex-col items-center gap-2">
          <span className="text-xs text-gray-500 uppercase tracking-wide">Simple</span>
          <SpellTooltip spell={spell} detailed={false} />
        </div>
        <div className="flex flex-col items-center gap-2">
          <span className="text-xs text-gray-500 uppercase tracking-wide">Detailed</span>
          <SpellTooltip spell={spell} detailed={true} />
        </div>
      </div>
      <a
        href={getTurtleWoWLink(spell.id)}
        target="_blank"
        rel="noopener noreferrer"
        className="text-sm text-blue-400 hover:text-blue-300 hover:underline"
      >
        View on TurtleWoW Database →
      </a>
    </div>
  );
}

const meta: Meta<typeof SpellTooltip> = {
  title: "WoWDB/SpellTooltip",
  component: SpellTooltip,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    backgrounds: { default: "dark" },
  },
  argTypes: {
    detailed: { 
      control: "boolean",
      description: "Show detailed view with duration and aura effects",
    },
  },
};

export default meta;
type Story = StoryObj<typeof meta>;

